const response = $input.first().json;
const script = response.choices[0].message.content;
const topic = $('Topic Picker').first().json.topic;
const episodeNumber = $('Topic Picker').first().json.episode_number;
const timestamp = new Date().toISOString().replace(/[:.]/g, '-');

const filename = `episode_${timestamp}.txt`;

return [{
  json: {
    script: script,
    topic: topic,
    episode_number: episodeNumber,
    filename: filename,
    timestamp: timestamp,
    title: `The Simba Show - ${topic}`,
    description: `Cat Podcast: ${topic}\n\nSimba and Meow are back with another episode!\n\n#CatPodcast #SimbaAndMeow #FunnyCats`
  }
}];

const response = $input.first().json;
const formatData = $('Format Script').first().json;

return [{
  json: {
    ...formatData,
    audio_path: response.audio_path || response.file,
    status: response.status || 'success',
    video_path: response.video_path,
    thumbnail_path: response.thumbnail_path
  }
}];

// Check if video was generated successfully
const data = $input.first().json;

if (data.status === 'success' && data.video_path) {
  return [{ json: { success: true, ...data } }];
} else {
  return [{ json: { success: false, error: 'Video generation failed', ...data } }];
}

const data = $input.first().json;

return [{
  json: {
    message: `Episode uploaded successfully!\nTitle: ${data.title}\nVideo ID: ${data.videoId}\nURL: https://youtube.com/watch?v=${data.videoId}`,
    timestamp: new Date().toISOString()
  }
}];

const data = $input.first().json;

return [{
  json: {
    message: `Episode failed: ${data.error}`,
    timestamp: new Date().toISOString(),
    topic: data.topic
  }
}];
